"""(Triforce VR) The hand controllers' icons in the game's button-icon font (nx2/prompt_assets.py faces_font adds them to every
face's font): the triggers (LT, RT) and grips (LG, RG) as the game's L, R, ZL and ZR with their letters cut anew, a swing, the
Menu, and the face buttons and stick presses as the game draws them. Each is at ICON_BASE + its place in ICONS (texts that name
one, as the pause menu's controls page does), and for each control scheme each Switch button has a code of its own at
SW_BASE + 16 x scheme + HOS_SW_* showing the VR control that presses it (MAP): host/prompts.c points the Switch buttons' code
points at those while a VR session plays, so every icon the game shows (the HUD's hints, the tutorial pop-ups, the icons in
texts) names the hand controllers' control.

The letters T and G come from the game's own ClarimoUDPE-DemiBold (LETTERS), sized to the icons' letters: without it the four
keep the game's L, R, ZL and ZR. The swing and the Menu are drawn here (SWING, MENU: outlines in the font's units, 1000 an em).
"""
LETTERS = "Font2/Scalable/ClarimoUDPE-DemiBold.Nin_Ounce_NVN2.bfotf.zs"
ICON_BASE = 0xF6C0
ICONS = ["lt", "rt", "lg", "rg", "swing", "menu", "a", "b", "x", "y", "ls_push", "rs_push", "blank"]
SW_BASE = 0xF680
SCHEMES = ["gesture", "simplified"]
# per Switch button (HOS_SW_*: A B X Y LS RS L R ZL ZR Plus Minus Left Up Right Down), the VR control's icon. Full Gesture: Y the
# sword's swing, X (jump) a stick's press, the triggers the item bars (L, R), the grip the item button (ZR), the X button the
# menus (Plus: a tap, Minus: a hold), the Z lock and the d-pad gestures (no button: none). Simplified: the left trigger the Z
# lock, the right trigger the item panel (its d-pad with the left stick), the right grip the item button
MAP = {
    "gesture": ["a", "b", "rs_push", "swing", "ls_push", "rs_push", "lt", "rt", "blank", "rg", "x", "x",
                "blank", "blank", "blank", "blank"],
    "simplified": ["a", "b", "rs_push", "swing", "ls_push", "rs_push", "blank", "rt", "lt", "rg", "x", "x",
                   "rt", "rt", "rt", "rt"],
}
# the game's own glyph for the face buttons, the stick presses and the blank (a full-width empty icon)
GAME = {"a": 0xE040, "b": 0xE041, "x": 0xE042, "y": 0xE043, "ls_push": 0xE056, "rs_push": 0xE057, "blank": 0xE04D}
# the triggers and grips: the game's icon whose shape each takes, its first letter's icon, the second letter
CUT = {"lt": (0xE044, 0xE046, "T"), "rt": (0xE045, 0xE047, "T"), "lg": (0xE046, 0xE046, "G"), "rg": (0xE047, 0xE047, "G")}
