def _contours(glyphset, name):
    from fontTools.pens.recordingPen import RecordingPen
    r = RecordingPen()
    glyphset[name].draw(r)
    out, cur = [], []
    for op in r.value:
        cur.append(op)
        if op[0] in ("closePath", "endPath"):
            out.append(cur)
            cur = []
    return out + ([cur] if cur else [])


def _play(ops, pen):
    for op, args in ops:
        getattr(pen, op)(*args)


def _bounds(ops):
    from fontTools.pens.boundsPen import BoundsPen
    b = BoundsPen(None)
    _play(ops, b)
    return b.bounds


def _area(ops):
    from fontTools.pens.areaPen import AreaPen
    a = AreaPen(None)
    _play(ops, a)
    return a.value


def _moved(ops, dx):
    from fontTools.pens.recordingPen import RecordingPen
    from fontTools.pens.transformPen import TransformPen
    r = RecordingPen()
    _play(ops, TransformPen(r, (1, 0, 0, 1, dx, 0)))
    return r.value


def _letters(gset, name):
    """an icon's outline (the largest contour) and its letters (the other contours, grouped by where they overlap side to side,
    left to right), each letter [contours] and its box"""
    cs = sorted(_contours(gset, name), key=lambda c: (lambda b: (b[2] - b[0]) * (b[3] - b[1]))(_bounds(c)), reverse=True)
    groups = []
    for c in sorted(cs[1:], key=lambda c: _bounds(c)[0]):
        b = _bounds(c)
        for g in groups:
            if b[0] < g[1][2] and b[2] > g[1][0]:
                g[0].append(c)
                g[1] = (min(g[1][0], b[0]), min(g[1][1], b[1]), max(g[1][2], b[2]), max(g[1][3], b[3]))
                break
        else:
            groups.append([[c], b])
    return cs[0], groups


def _letter(lset, lcmap, ch, cap, base, hole):
    """a letter of the letters' font as a hole of the icons' letter height (cap) on their baseline"""
    from fontTools.pens.recordingPen import RecordingPen
    from fontTools.pens.reverseContourPen import ReverseContourPen
    from fontTools.pens.transformPen import TransformPen
    cs = _contours(lset, lcmap[ord(ch)])
    b = _bounds([op for c in cs for op in c])
    s = cap / (b[3] - b[1])
    out = []
    for c in cs:
        r = RecordingPen()
        t = TransformPen(r, (s, 0, 0, s, -b[0] * s, base - b[1] * s))
        _play(c, ReverseContourPen(t) if (_area(c) > 0) != hole else t)
        out.append(r.value)
    return [out, (0, base, (b[2] - b[0]) * s, base + cap)]


def add_icons(gset, cmap, chars, hmtx, add, copy, letters=None):
    """the VR icons added to the font being made (faces_font's add and copy); {code: glyph name} of ICON_BASE's and SW_BASE's"""
    import io
    from fontTools.pens.t2CharStringPen import T2CharStringPen
    from fontTools.ttLib import TTFont

    names = {}
    for k, code in GAME.items():
        names[k] = copy(f"vr_{k}", cmap[code])
    lset = lcmap = None
    if letters:
        lt = TTFont(io.BytesIO(letters))
        lset, lcmap = lt.getGlyphSet(), lt.getBestCmap()
    two = _letters(gset, cmap[0xE046])[1]   # (ZL's two letters: the size and spacing of a two-letter icon)
    cap, base, gap = two[1][1][3] - two[1][1][1], two[1][1][1], two[1][1][0] - two[0][1][2]
    hole = _area(two[1][0][0]) > 0
    for k, (shape_code, first_code, second) in CUT.items():
        ref = cmap[shape_code]
        width = hmtx[ref][0]
        if not lset or ord(second) not in lcmap:
            names[k] = copy(f"vr_{k}", ref)
            continue
        outline, groups = _letters(gset, ref)
        first = _letters(gset, cmap[first_code])[1][-1]   # (the L or R of a two-letter icon: its size)
        mid = (groups[0][1][0] + groups[-1][1][2]) / 2
        b = _letter(lset, lcmap, second, cap, base, hole)
        wa, wb = first[1][2] - first[1][0], b[1][2] - b[1][0]
        x0 = mid - (wa + gap + wb) / 2
        pen = T2CharStringPen(width, None)
        _play(outline, pen)
        for c in first[0]:
            _play(_moved(c, x0 - first[1][0]), pen)
        for c in b[0]:
            _play(_moved(c, x0 + wa + gap - b[1][0]), pen)
        cs = chars[ref]
        names[k] = add(f"vr_{k}", pen.getCharString(private=cs.private, globalSubrs=cs.globalSubrs), width)
    for k, (width, contours) in (("swing", SWING), ("menu", MENU)):
        pen = T2CharStringPen(width, None)
        for c in contours:
            pen.moveTo(c[0])
            for p in c[1:]:
                pen.lineTo(p)
            pen.closePath()
        cs = chars[cmap[0xE040]]
        names[k] = add(f"vr_{k}", pen.getCharString(private=cs.private, globalSubrs=cs.globalSubrs), width)
    placed = {ICON_BASE + i: names[k] for i, k in enumerate(ICONS)}
    for s, scheme in enumerate(SCHEMES):
        for b, k in enumerate(MAP[scheme]):
            placed[SW_BASE + 16 * s + b] = names[k]
    return placed
